try:asyncio.run(main())
except Exception as e:
 results.append({'name':'runner exception','pass':False,'detail':traceback.format_exc()});print(traceback.format_exc())
finally:
 OUT.joinpath('test-results.json').write_text(json.dumps({'checks':results,'errors':errors,'requests':sorted(set(network))},indent=2));print('RESULT',sum(x['pass'] for x in results),'/',len(results))
